  "Себестоимость действует с начала выбранного дня: поступления этого дня затем меняют среднюю себестоимость. Документы с этой даты пересчитываются автоматически.": "The cost price applies from the start of the selected day: that day's receipts then change the average cost. Documents from this date are recalculated automatically.",
  "Неактивный прайс-лист не может быть по умолчанию для заказа": "An inactive price list cannot be the default for orders",
  "Прайс-лист по умолчанию для заказа нельзя отключить: сначала назначьте по умолчанию другой прайс-лист или снимите эту отметку": "The default price list for orders cannot be deactivated: first make another price list the default or untick this option",
  "Прайс-лист по умолчанию для заказа нельзя удалить: сначала назначьте по умолчанию другой прайс-лист или снимите эту отметку": "The default price list for orders cannot be deleted: first make another price list the default or untick this option",
  "Курс к базовой валюте": "Rate to the base currency",
  "Базовой валюты ещё нет: первая валюта станет базовой, поэтому её курс должен быть 1.": "There is no base currency yet: the first currency becomes the base one, so its rate must be 1.",
  "Базовой валюты ещё нет: первая валюта становится базовой, её курс должен быть 1": "There is no base currency yet: the first currency becomes the base one, its rate must be 1",
  "Базовой валюты ещё нет: добавьте в файл базовую валюту с курсом 1": "There is no base currency yet: add the base currency with rate 1 to the file",
  "Новая себестоимость действует с того же момента, что и прежняя: документы с этого момента пересчитываются автоматически.": "The new cost price applies from the same moment as the previous one: documents from that moment are recalculated automatically.",
  "Новые строки с сегодняшней датой действуют с момента импорта, остальные — с начала своего дня. Строка уже добавленной себестоимости (тот же товар, дата и склад) исправляет её с прежнего момента.": "New rows dated today apply from the moment of the import, the others from the start of their day. A row for a cost price already added (same product, date and warehouse) corrects it from its original moment.",

